INSERT INTO gradiva (id_gradivo, id_predmet, nalozil, naslov, vrsta, vsebina, datoteka_ime, datoteka_url, tip_datoteke, velikost_bajtov, dodano_ob, izbrisano_ob) VALUES
    (1, 1, 2, 'Kvadratna funkcija', 'Zapiski', 'Kvadratna funkcija ima obliko f(x) = ax² + bx + c. Njen graf je parabola. Če je a pozitiven, je parabola obrnjena navzgor. Teme izračunamo z x = −b / (2a).', NULL, NULL, NULL, NULL, '2026-10-28 12:00:00', NULL),
    (2, 1, 2, 'Vaje · Kvadratna funkcija', 'Vaje', 'Narišite grafe funkcij f(x) = x², g(x) = x² − 4 in h(x) = (x − 2)². Označite teme in ničle ter priložite postopek.
INSERT INTO naloge (id_naloga, id_predmet, ustvaril, naslov, navodila, rok_oddaje, ustvarjeno_ob) VALUES
    (1, 1, 2, 'Kviz: kvadratna funkcija', 'Pripravite kratek povzetek poglavja in tri vprašanja za ponavljanje. Pri vsakem vprašanju napišite tudi odgovor.', '2026-10-23', '2026-10-09 09:00:00'),
    (2, 1, 2, 'Graf kvadratne funkcije', 'Narišite grafe funkcij f(x) = x², g(x) = x² − 4 in h(x) = (x − 2)². Označite teme in ničle ter priložite postopek.', '2026-10-31', '2026-10-16 09:00:00'),
    (3, 1, 2, 'Ponavljanje: kvadratna funkcija', 'Pripravite kratek povzetek poglavja in tri vprašanja za ponavljanje. Pri vsakem vprašanju napišite tudi odgovor.', '2026-11-08', '2026-10-16 09:00:00'),
    (4, 2, 3, 'Kviz: slovenska moderna', 'Pripravite kratek povzetek poglavja in tri vprašanja za ponavljanje. Pri vsakem vprašanju napišite tudi odgovor.', '2026-10-22', '2026-10-08 09:00:00'),
    (5, 2, 3, 'Interpretacija pesmi', 'Izberite pesem iz obravnavanega sklopa. V 300 besedah opišite temo, motive in pesniška sredstva. Svoje ugotovitve podprite s primeri.', '2026-11-01', '2026-10-16 09:00:00'),
    (6, 2, 3, 'Ponavljanje: slovenska moderna', 'Pripravite kratek povzetek poglavja in tri vprašanja za ponavljanje. Pri vsakem vprašanju napišite tudi odgovor.', '2026-11-09', '2026-10-16 09:00:00'),
    (7, 3, 4, 'Kviz: writing an opinion essay', 'Pripravite kratek povzetek poglavja in tri vprašanja za ponavljanje. Pri vsakem vprašanju napišite tudi odgovor.', '2026-10-21', '2026-10-07 09:00:00'),
    (8, 3, 4, 'An opinion essay', 'Write a 200-word essay about learning online. Include an introduction, two arguments and a conclusion.', '2026-11-02', '2026-10-16 09:00:00'),
    (9, 3, 4, 'Ponavljanje: writing an opinion essay', 'Pripravite kratek povzetek poglavja in tri vprašanja za ponavljanje. Pri vsakem vprašanju napišite tudi odgovor.', '2026-11-10', '2026-10-16 09:00:00'),
    (10, 4, 5, 'Kviz: zanke in polja', 'Pripravite kratek povzetek poglavja in tri vprašanja za ponavljanje. Pri vsakem vprašanju napišite tudi odgovor.', '2026-10-20', '2026-10-06 09:00:00'),
    (11, 4, 5, 'Obdelava seznama števil', 'Napišite program, ki izračuna najmanjšo, največjo in povprečno vrednost v polju. Oddajte izvorno kodo z opisom preizkusov.', '2026-11-03', '2026-10-16 09:00:00'),
    (12, 4, 5, 'Ponavljanje: zanke in polja', 'Pripravite kratek povzetek poglavja in tri vprašanja za ponavljanje. Pri vsakem vprašanju napišite tudi odgovor.', '2026-11-11', '2026-10-16 09:00:00'),
    (13, 5, 6, 'Kviz: načrtovanje storitve', 'Pripravite kratek povzetek poglavja in tri vprašanja za ponavljanje. Pri vsakem vprašanju napišite tudi odgovor.', '2026-10-19', '2026-10-05 09:00:00'),
    (14, 5, 6, 'Predlog računalniške storitve', 'Opišite uporabnike, namen in potek izbrane računalniške storitve. Dodajte primer uporabe.', '2026-11-04', '2026-10-16 09:00:00'),
    (15, 5, 6, 'Ponavljanje: načrtovanje storitve', 'Pripravite kratek povzetek poglavja in tri vprašanja za ponavljanje. Pri vsakem vprašanju napišite tudi odgovor.', '2026-11-12', '2026-10-16 09:00:00'),
    (16, 6, 7, 'Kviz: semantični html', 'Pripravite kratek povzetek poglavja in tri vprašanja za ponavljanje. Pri vsakem vprašanju napišite tudi odgovor.', '2026-10-18', '2026-10-04 09:00:00'),
    (17, 6, 7, 'Dostopna spletna stran', 'Izdelajte stran z navigacijo, glavno vsebino in obrazcem. Uporabite semantične elemente in oznake za vsa vnosna polja.', '2026-11-05', '2026-10-16 09:00:00'),
    (18, 6, 7, 'Ponavljanje: semantični html', 'Pripravite kratek povzetek poglavja in tri vprašanja za ponavljanje. Pri vsakem vprašanju napišite tudi odgovor.', '2026-11-13', '2026-10-16 09:00:00'),
    (19, 7, 8, 'Kviz: razširjena resničnost', 'Pripravite kratek povzetek poglavja in tri vprašanja za ponavljanje. Pri vsakem vprašanju napišite tudi odgovor.', '2026-10-17', '2026-10-03 09:00:00'),
    (20, 7, 8, 'Primer uporabe novih tehnologij', 'Predstavite konkreten primer uporabe razširjene resničnosti. Ocenite prednosti in omejitve.', '2026-11-06', '2026-10-16 09:00:00'),
    (21, 7, 8, 'Ponavljanje: razširjena resničnost', 'Pripravite kratek povzetek poglavja in tri vprašanja za ponavljanje. Pri vsakem vprašanju napišite tudi odgovor.', '2026-11-14', '2026-10-16 09:00:00'),
    (22, 8, 9, 'Kviz: družbene skupine', 'Pripravite kratek povzetek poglavja in tri vprašanja za ponavljanje. Pri vsakem vprašanju napišite tudi odgovor.', '2026-10-16', '2026-10-02 09:00:00'),
    (23, 8, 9, 'Opazovanje družbene skupine', 'Opišite družbeno skupino, njene norme in vloge. Uporabite anonimiziran primer brez osebnih podatkov.', '2026-11-07', '2026-10-16 09:00:00'),
    (24, 8, 9, 'Ponavljanje: družbene skupine', 'Pripravite kratek povzetek poglavja in tri vprašanja za ponavljanje. Pri vsakem vprašanju napišite tudi odgovor.', '2026-11-15', '2026-10-16 09:00:00'),
